    unsigned char buf[65536];
    long lines = 0, words = 0, bytes = 0;
    size_t maxlen = 0, cur_line_len = 0;
    int in_word = 0; /* inside a word */
    int has_chars_eof = 0; /* last chunk ended with un-terminated line chars */

    while (1) {
        ssize_t n = read(STDIN_FILENO, buf, sizeof(buf));
        if (n <= 0) break;

        for (ssize_t i = 0; i < n; i++) {
            unsigned char b = buf[i];

            /* byte counting */
            bytes++;

            /* line counting and max-line tracking */
            cur_line_len++;

            if (b == '\n') {
                lines++;
                if (cur_line_len > maxlen)
                    maxlen = cur_line_len;
                cur_line_len = 0;
            }
